package com.vr3th.mediacompressor.ui.screens
import android.net.Uri;import androidx.activity.compose.rememberLauncherForActivityResult;import androidx.activity.result.contract.ActivityResultContracts;import androidx.compose.foundation.layout.*;import androidx.compose.material3.*;import androidx.compose.runtime.Composable;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp
@Composable fun ExtractScreen(onExtractAudio:(Uri)->Unit,onExtractGif:(Uri)->Unit,onExtractZip:(Uri)->Unit,onBack:()->Unit){val a=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){it?.let(onExtractAudio)};val g=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){it?.let(onExtractGif)};val z=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){it?.let(onExtractZip)};Column(Modifier.fillMaxSize().padding(20.dp),verticalArrangement=Arrangement.spacedBy(16.dp)){Text("Extraction Lab",style=MaterialTheme.typography.titleLarge);Button({a.launch(arrayOf("video/*"))},Modifier.fillMaxWidth()){Text("Video → Audio (Lossless)")};Button({g.launch(arrayOf("video/*"))},Modifier.fillMaxWidth()){Text("Video → GIF Animation")};Button({z.launch(arrayOf("application/zip","application/octet-stream"))},Modifier.fillMaxWidth()){Text("Extract ZIP Archive")};TextButton(onClick=onBack){Text("Back")}}}
